import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { collection, query, where, onSnapshot, doc, getDoc, orderBy, updateDoc } from 'firebase/firestore';
import { db, auth } from '../../firebase';
import { onAuthStateChanged } from 'firebase/auth';
import CryptoJS from 'crypto-js';

const ChatListPage = () => {
  const [user, setUser] = useState(null);
  const [chats, setChats] = useState([]);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();
  const secretKey = 'Kibzar'; // Replace with your secret key

  const fetchUserName = async (userId) => {
    try {
      const userDoc = await getDoc(doc(db, 'users', userId));
      if (userDoc.exists()) {
        return userDoc.data().name || 'Unknown User';
      }
      return 'Unknown User';
    } catch (error) {
      console.error('Error fetching user name:', error);
      return 'Unknown User';
    }
  };

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  useEffect(() => {
    if (user) {
      const q = query(
        collection(db, 'chats'),
        where('userId', '==', user.uid),
        orderBy('timestamp', 'desc')
      );

      const unsubscribe = onSnapshot(
        q,
        async (querySnapshot) => {
          const chatList = await Promise.all(
            querySnapshot.docs.map(async (doc) => {
              const chatData = doc.data();

              // Decrypt message
              let decryptedMessage = '';
              try {
                decryptedMessage = CryptoJS.AES.decrypt(chatData.message, secretKey).toString(CryptoJS.enc.Utf8);
              } catch (error) {
                console.error('Error decrypting message:', error);
                decryptedMessage = 'Unable to decrypt message.';
              }

              // Fetch recipient name
              const recipientId = chatData.recipientId === user.uid ? chatData.userId : chatData.recipientId;
              const recipientName = await fetchUserName(recipientId);

              return {
                id: doc.id,
                ...chatData,
                message: decryptedMessage,
                recipientName,
              };
            })
          );

          setChats(chatList);
          setLoading(false);
        },
        (error) => {
          console.error('Error fetching chats:', error);
          setLoading(false);
        }
      );

      return () => unsubscribe();
    }
  }, [user]);

  const handleChatClick = async (chat) => {
    console.log('Navigating to chat with conversationId:', chat.conversationId);

    // Mark the chat as read
    try {
      const chatDoc = doc(db, 'chats', chat.id);
      await updateDoc(chatDoc, { isRead: true });
    } catch (error) {
      console.error('Error updating read status:', error);
    }

    navigate(`/chat/${chat.postId}`, {
      state: {
        conversationId: chat.conversationId,
        postId: chat.postId,
        recipientId: chat.recipientId,
        recipientName: chat.recipientName,
      },
    });
  };

  if (loading) {
    return <p className="text-gray-500 text-center">Loading chats...</p>;
  }

  return (
    <div className="container mx-auto px-4 py-8">
      <h1 className="text-2xl font-semibold mb-4">Chats</h1>
      <div className="bg-white p-4 rounded-lg shadow-md">
        {chats.length > 0 ? (
          chats.map((chat) => (
            <div
              key={chat.id}
              className={`mb-2 p-2 rounded-lg bg-gray-100 cursor-pointer ${
                chat.isRead ? '' : 'bg-blue-100'
              }`}
              onClick={() => handleChatClick(chat)}
            >
              <p className="text-sm font-bold">{chat.recipientName}</p>
              <p className="text-sm text-gray-600">{chat.message}</p>
              <small className="text-gray-400">
                {new Date(chat.timestamp.seconds * 1000).toLocaleString()}
              </small>
              {!chat.isRead && (
                <span className="text-xs text-red-500 font-semibold">New</span>
              )}
            </div>
          ))
        ) : (
          <p className="text-gray-600">No chats available</p>
        )}
      </div>
    </div>
  );
};

export default ChatListPage;
